# Generated by build.py from recipe.yml for recipe sftp-keep-a-pinned-host-key-across-restarts. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'rekeyed' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'rekeyed/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'pin.sh'), "#!/bin/sh`n# Usage: sh pin.sh KEY.pub > pin.cfg`nfingerprint=`$(ssh-keygen -l -f `"`$1`" | cut -d' ' -f2 | sed 's/^SHA256://')`nprintf 'hostpubsha256 = `"%s`"\n' `"`$fingerprint`"`n")
cmd /c 'ssh-keygen -q -t rsa -b 3072 -N "" -f host_key'
cmd /c 'ssh-keygen -q -t rsa -b 3072 -N "" -f other_key'
cmd /c 'sh pin.sh host_key.pub > pin.cfg'
$server0 = Start-Process surl -ArgumentList '-v', '--directory', 'site', '--log-file', 'main.log', '--hostkey', 'host_key', '--user', 'alice:s3cret', 'sftp://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -sS -K pin.cfg -u alice:s3cret sftp://127.0.0.1:8080/hello.txt } finally { Stop-Process $server0 }
